package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type LoanRec struct {
	LrAcct      string
	LrPrincipal decimal.Decimal
	LrRate      decimal.Decimal
	LrYears     int64
}

var WsEofFlag string = "N"
var WsInterest decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsPrinEd string
var WsIntEd string
var WsTotalEd string

var loanRec LoanRec

var inputLines []string
var inputIdx int
var inputOpened bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) decimal.Decimal {
	return decimal.New(1, int32(n))
}

func storePic9(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	n := intDigits + int(scale)
	mod := pow10(n)
	// shift to unscaled integer
	unscaled := v.Shift(scale).Truncate(0)
	// modulo keeping low-order digits
	neg := unscaled.IsNegative()
	abs := unscaled.Abs()
	rem := abs.Mod(mod)
	if neg {
		rem = rem.Neg()
		// COBOL unsigned would drop sign; but keep negative remainder semantics
		// rem is in (-mod, 0]
	}
	return rem.Shift(-scale)
}

func formatEdited(v decimal.Decimal, pic string) string {
	dotIdx := strings.Index(pic, ".")
	var intPic, fracPic string
	hasDot := dotIdx >= 0
	if hasDot {
		intPic = pic[:dotIdx]
		fracPic = pic[dotIdx+1:]
	} else {
		intPic = pic
		fracPic = ""
	}
	nInt := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			nInt++
		}
	}
	nFrac := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			nFrac++
		}
	}
	neg := v.IsNegative()
	abs := v.Abs()
	var trunc decimal.Decimal
	if nFrac > 0 {
		trunc = abs.Truncate(int32(nFrac))
	} else {
		trunc = abs.Truncate(0)
	}
	intPart := trunc.Truncate(0)
	var intMod decimal.Decimal
	if nInt > 0 {
		mod := pow10(nInt)
		intMod = intPart.Mod(mod)
	} else {
		intMod = decimal.NewFromInt(0)
	}
	intStr := intMod.StringFixed(0)
	// StringFixed may include minus; but intMod >=0 here
	if strings.HasPrefix(intStr, "-") {
		intStr = intStr[1:]
	}
	// remove any decimal point (shouldn't be)
	if idx := strings.Index(intStr, "."); idx >= 0 {
		intStr = intStr[:idx]
	}
	if len(intStr) < nInt {
		intStr = strings.Repeat("0", nInt-len(intStr)) + intStr
	} else if len(intStr) > nInt {
		intStr = intStr[len(intStr)-nInt:]
	}
	padded := intStr
	// first non-zero
	firstNZ := -1
	for i := 0; i < nInt; i++ {
		if padded[i] != '0' {
			firstNZ = i
			break
		}
	}
	if firstNZ == -1 {
		firstNZ = nInt - 1
		if nInt == 0 {
			firstNZ = 0
		}
	}
	// fractional digits
	fracStr := ""
	if nFrac > 0 {
		fracPart := trunc.Sub(intPart).Shift(int32(nFrac)).Truncate(0)
		fs := fracPart.StringFixed(0)
		if strings.HasPrefix(fs, "-") {
			fs = fs[1:]
		}
		if idx := strings.Index(fs, "."); idx >= 0 {
			fs = fs[:idx]
		}
		if len(fs) < nFrac {
			fs = strings.Repeat("0", nFrac-len(fs)) + fs
		} else if len(fs) > nFrac {
			fs = fs[len(fs)-nFrac:]
		}
		fracStr = fs
	}
	// build integer output
	var b strings.Builder
	k := 0
	printedDigit := false
	fracK := 0
	// helper to peek: for comma decision use printedDigit
	for _, c := range intPic {
		switch c {
		case 'Z', '9':
			d := padded[k]
			if c == '9' {
				b.WriteByte(d)
				printedDigit = true
			} else {
				if k < firstNZ {
					b.WriteByte(' ')
				} else {
					b.WriteByte(d)
					printedDigit = true
				}
			}
			k++
		case ',':
			if printedDigit {
				b.WriteByte(',')
			} else {
				b.WriteByte(' ')
			}
		case '.':
			b.WriteByte('.')
		default:
			b.WriteByte(byte(c))
		}
	}
	if hasDot {
		b.WriteByte('.')
		for _, c := range fracPic {
			switch c {
			case 'Z', '9':
				if fracK < len(fracStr) {
					b.WriteByte(fracStr[fracK])
				} else {
					b.WriteByte('0')
				}
				fracK++
			default:
				b.WriteByte(byte(c))
			}
		}
	}
	_ = neg
	return b.String()
}

func parseImplied(s string, scale int32) decimal.Decimal {
	t := strings.TrimSpace(s)
	if t == "" {
		return decimal.NewFromInt(0)
	}
	// keep only digits and sign
	neg := false
	var digits strings.Builder
	for i, c := range t {
		if i == 0 && (c == '+' || c == '-') {
			if c == '-' {
				neg = true
			}
			continue
		}
		if c >= '0' && c <= '9' {
			digits.WriteRune(c)
		} else if c == ' ' {
			continue
		} else {
			// ignore other chars? treat as zero? skip
		}
	}
	dstr := digits.String()
	if dstr == "" {
		return decimal.NewFromInt(0)
	}
	// strip leading zeros for conversion but keep at least one
	dstrTrim := strings.TrimLeft(dstr, "0")
	if dstrTrim == "" {
		return decimal.NewFromInt(0)
	}
	d, err := decimal.NewFromString(dstrTrim)
	if err != nil {
		return decimal.NewFromInt(0)
	}
	d = d.Shift(-scale)
	if neg {
		d = d.Neg()
	}
	return d
}

func parseIntField(s string) int64 {
	t := strings.TrimSpace(s)
	if t == "" {
		return 0
	}
	neg := false
	var digits strings.Builder
	for i, c := range t {
		if i == 0 && (c == '+' || c == '-') {
			if c == '-' {
				neg = true
			}
			continue
		}
		if c >= '0' && c <= '9' {
			digits.WriteRune(c)
		}
	}
	dstr := digits.String()
	if dstr == "" {
		return 0
	}
	var v int64 = 0
	for _, c := range dstr {
		v = v*10 + int64(c-'0')
	}
	if neg {
		v = -v
	}
	return v
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func MainPara() {
	// OPEN INPUT LOAN-FILE
	f, err := os.Open("input.dat")
	if err != nil {
		// empty file behaviour: treat as no records
		inputLines = []string{}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		sc.Buffer(make([]byte, 1024*1024), 1024*1024)
		for sc.Scan() {
			line := sc.Text()
			// strip trailing \r if present (scanner strips \n, keeps \r? Actually ScanLines strips \r\n)
			if strings.HasSuffix(line, "\r") {
				line = line[:len(line)-1]
			}
			inputLines = append(inputLines, line)
		}
		f.Close()
	}
	inputIdx = 0
	inputOpened = true
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE LOAN-FILE (nothing)
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad with spaces to 21
	if len(line) < 21 {
		line = line + strings.Repeat(" ", 21-len(line))
	} else if len(line) > 21 {
		line = line[:21]
	}
	acct := line[0:6]
	prStr := line[6:15]
	rateStr := line[15:19]
	yrStr := line[19:21]
	loanRec.LrAcct = acct
	loanRec.LrPrincipal = parseImplied(prStr, 2)
	loanRec.LrRate = parseImplied(rateStr, 2)
	loanRec.LrYears = parseIntField(yrStr)
}

func ProcessPara() {
	// COMPUTE WS-INTEREST ROUNDED = LR-PRINCIPAL * LR-RATE * LR-YEARS / 100
	yrDec := decimal.NewFromInt(loanRec.LrYears)
	tmp := loanRec.LrPrincipal.Mul(loanRec.LrRate).Mul(yrDec).Shift(-2)
	tmp = tmp.Round(2)
	tmp = storePic9(tmp, 9, 2)
	WsInterest = tmp
	// ADD WS-INTEREST TO WS-TOTAL
	WsTotal = storePic9(WsTotal.Add(WsInterest), 11, 2)
	// ADD 1 TO WS-COUNT
	WsCount = (WsCount + 1) % 100000
	if WsCount < 0 {
		WsCount += 100000
	}
	WsPrinEd = formatEdited(loanRec.LrPrincipal, "Z,ZZZ,ZZ9.99")
	WsIntEd = formatEdited(WsInterest, "ZZZ,ZZZ,ZZ9.99")
	out := loanRec.LrAcct + " " + WsPrinEd + " " + WsIntEd
	fmt.Fprint(os.Stdout, out+"\n")
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotal, "ZZ,ZZZ,ZZZ,ZZ9.99")
	countStr := fmt.Sprintf("%05d", WsCount)
	fmt.Fprint(os.Stdout, "RECORDS: "+countStr+"\n")
	fmt.Fprint(os.Stdout, "TOTAL INTEREST: "+WsTotalEd+"\n")
}

func main() {
	MainPara()
}
